	for _, e := range os.Environ() {
		k := strings.SplitN(e, "=", 2)
		if len(k) == 2 && strings.HasPrefix(k[0], "PORT_") && len(k[0]) > 5 {
			kr.MeshEnv[k[0]] = k[1]
		}
	}
