// go runs the KRun instance.
func (k *KRun) go(ctx context.Context) error {
	// Set up a channel to listen for termination signals
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	// Start the application
	if err := k.startApp(ctx); err != nil {
		return fmt.Errorf("failed to start application: %w", err)
	}

	// Wait for termination signal
	select {
	case sig := <-sigCh:
		log.Printf("Received signal: %s", sig)
		if err := k.stopApp(); err != nil {
			return fmt.Errorf("failed to stop application: %w", err)
		}
	case <-ctx.Done():
		log.Println("Context done, stopping application.")
		if err := k.stopApp(); err != nil {
			return fmt.Errorf("failed to stop application: %w", err)
		}
	}

	return nil
}

