type controlItem interface {
	isItem() bool
}

type controlBuffer struct {
	mu      sync.Mutex
	items   []controlItem
	cond    *sync.Cond
	closed  bool
}

func newControlBuffer() *controlBuffer {
	cb := &controlBuffer{}
	cb.cond = sync.NewCond(&cb.mu)
	return cb
}

func (cb *controlBuffer) put(item controlItem) {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	if cb.closed {
		return
	}
	cb.items = append(cb.items, item)
	cb.cond.Signal()
}

func (cb *controlBuffer) get() controlItem {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	for len(cb.items) == 0 && !cb.closed {
		cb.cond.Wait()
	}
	if cb.closed {
		return nil
	}
	item := cb.items[0]
	cb.items = cb.items[1:]
	return item
}

func (cb *controlBuffer) close() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.closed = true
	cb.cond.Broadcast()
}

