func (l *Librato) Write(metrics []telegraf.Metric) error {
	lMetrics := &LMetrics{}

	for _, metric := range metrics {
		for _, field := range metric.FieldList() {
			gauge := &Gauge{
				Name:        fmt.Sprintf("%s.%s", metric.Measurement(), field.Key),
				Value:       field.Value.(float64),
				Source:      l.getSource(metric),
				MeasureTime: metric.Time().Unix(),
			}
			lMetrics.Gauges = append(lMetrics.Gauges, gauge)
		}
	}

	return l.send(lMetrics)
}

func (l *Librato) getSource(metric telegraf.Metric) string {
	if l.SourceTag != "" {
		if source, ok := metric.GetTag(l.SourceTag); ok {
			return source
		}
	}
	return metric.Tags()["host"]
}

