func (t *Triangle) Area() float64 {
	e1 := t.v2.Sub(t.v1)
	e2 := t.v3.Sub(t.v1)
	n := e1.Cross(e2)
	return n.Length() / 2
}

func (t *Triangle) Barycentric(p Vector) (u, v, w float64) {
	v0 := t.v2.Sub(t.v1)
	v1 := t.v3.Sub(t.v1)
	v2 := p.Sub(t.v1)
	d00 := v0.Dot(v0)
	d01 := v0.Dot(v1)
	d11 := v1.Dot(v1)
	d20 := v2.Dot(v0)
	d21 := v2.Dot(v1)
	d := d00*d11 - d01*d01
	v = (d11*d20 - d01*d21) / d
	w = (d00*d21 - d01*d20) / d
	u = 1 - v - w
	return
}

func (t *Triangle) UpdateBox() {
	min := t.v1.Min(t.v2).Min(t.v3)
	max := t.v1.Max(t.v2).Max(t.v3)
	t.box = Box{min, max}
}

