func (s *Store) go() {
	ticker := time.NewTicker(defaultDefaultTTL)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			s.cleanupExpiredEntries()
		}
	}
}

func (s *Store) cleanupExpiredEntries() {
	now := time.Now()
	expiredEntries := []string{}

	s.mu.Lock()
	defer s.mu.Unlock()

	for key, entry := range s.entries {
		if entry.expiry.Before(now) {
			expiredEntries = append(expiredEntries, key)
		}
	}

	for _, key := range expiredEntries {
		delete(s.entries, key)
	}
}

